+    private void showAtScale(double scaleX, double scaleY) {
+        borderpane.setManaged(false);
+        Pane root = new Pane(borderpane);
+        stage = new Stage();
+        stage.renderScaleXProperty().bind(new SimpleDoubleProperty(scaleX));
